// GEOMETRIC PRIMITIVES

// Cross product of vectors (B-A) and (C-A)
// Returns: positive (CCW), negative (CW), 0 (collinear)
function cross(A, B, C) {
    return (B[0]-A[0]) * (C[1]-A[1]) - (B[1]-A[1]) * (C[0]-A[0]);
}

// Orientation of three points: 0=collinear, 1=CCW, 2=CW
function orientation(A, B, C) {
    const val = cross(A, B, C);
    if (val === 0) return 0;  // collinear
    return val > 0 ? 1 : 2;  // 1=CCW, 2=CW
}

// Check if point Q lies on segment PR
function onSegment(P, Q, R) {
    return Math.min(P[0],R[0]) <= Q[0] && Q[0] <= Math.max(P[0],R[0]) &&
           Math.min(P[1],R[1]) <= Q[1] && Q[1] <= Math.max(P[1],R[1]);
}

// Do segments AB and CD intersect?
function segmentsIntersect(A, B, C, D) {
    const o1 = orientation(A, B, C);
    const o2 = orientation(A, B, D);
    const o3 = orientation(C, D, A);
    const o4 = orientation(C, D, B);

    if (o1 !== o2 && o3 !== o4) return true; // general case

    // Collinear special cases
    if (o1 === 0 && onSegment(A, C, B)) return true;
    if (o2 === 0 && onSegment(A, D, B)) return true;
    if (o3 === 0 && onSegment(C, A, D)) return true;
    if (o4 === 0 && onSegment(C, B, D)) return true;
    return false;
}

console.log(segmentsIntersect([0,0],[1,1],[0,1],[1,0])); // true (X shape)
console.log(segmentsIntersect([0,0],[1,1],[2,2],[3,3])); // false (parallel)

// POINT IN POLYGON (ray casting)
function pointInPolygon(point, polygon) {
    let [px, py] = point;
    let inside = false;
    const n = polygon.length;
    for (let i = 0, j = n-1; i < n; j = i++) {
        const [xi,yi] = polygon[i], [xj,yj] = polygon[j];
        if ((yi > py) !== (yj > py) &&
            px < (xj-xi)*(py-yi)/(yj-yi)+xi) {
            inside = !inside;
        }
    }
    return inside;
}

