// GRAHAM SCAN CONVEX HULL — O(n log n)
function convexHull(points) {
    if (points.length <= 2) return points;

    // Find anchor: lowest y, then leftmost x
    let anchor = points[0];
    for (const p of points) {
        if (p[1] < anchor[1] || (p[1] === anchor[1] && p[0] < anchor[0])) {
            anchor = p;
        }
    }

    // Sort by polar angle from anchor
    const others = points.filter(p => p !== anchor);
    others.sort((A, B) => {
        const c = cross(anchor, A, B); // anchor, A, B
        if (c !== 0) return c > 0 ? -1 : 1; // CCW first (larger angle last)
        // Collinear: sort by distance from anchor
        const distA = (A[0]-anchor[0])**2 + (A[1]-anchor[1])**2;
        const distB = (B[0]-anchor[0])**2 + (B[1]-anchor[1])**2;
        return distA - distB;
    });

    // Stack-based hull construction
    const hull = [anchor];
    for (const p of others) {
        while (hull.length >= 2) {
            const top = hull[hull.length-1];
            const prev = hull[hull.length-2];
            if (cross(prev, top, p) <= 0) { // not CCW: pop
                hull.pop();
            } else break;
        }
        hull.push(p);
    }
    return hull;
}

