// RECTANGLE AREA II (#850) — line sweep with coordinate compression
function rectangleArea(rectangles) {
    const MOD = 1e9 + 7;
    // Coordinate compress y values
    const ySet = new Set();
    for (const [x1,y1,x2,y2] of rectangles) { ySet.add(y1); ySet.add(y2); }
    const yCoords = [...ySet].sort((a,b)=>a-b);
    const yMap = new Map(yCoords.map((y,i)=>[y,i]));
    const m = yCoords.length;

    // Events: [x, type, y1, y2] where type: 1=start, -1=end
    const events = [];
    for (const [x1,y1,x2,y2] of rectangles) {
        events.push([x1,  1, y1, y2]);
        events.push([x2, -1, y1, y2]);
    }
    events.sort((a,b) => a[0]-b[0]);

    // Count array: count[i] = number of active rectangles covering y-interval i
    const count = new Array(m).fill(0);
    let prevX = 0, result = 0;

    for (const [x, type, y1, y2] of events) {
        // Compute covered y-length with current active set
        let coveredY = 0, cover = 0;
        for (let i = 0; i < m-1; i++) {
            if (count[i] > 0) coveredY += yCoords[i+1] - yCoords[i];
        }
        result = (result + coveredY * (x - prevX)) % MOD;
        prevX = x;

        // Update count for this event's y-range
        for (let i = yMap.get(y1); i < yMap.get(y2); i++) {
            count[i] += type; // +1 for start, -1 for end
        }
    }
    return result;
}

