// CLOSEST PAIR OF POINTS — O(n log^2 n)
function dist(p1, p2) {
    return Math.sqrt((p1[0]-p2[0])**2 + (p1[1]-p2[1])**2);
}

function closestPair(points) {
    points.sort((a,b) => a[0]-b[0]); // sort by x
    return _closest(points);
}

function _closest(pts) {
    const n = pts.length;
    if (n <= 3) {
        let minD = Infinity;
        for (let i=0;i<n;i++) for (let j=i+1;j<n;j++)
            minD = Math.min(minD, dist(pts[i], pts[j]));
        return minD;
    }
    const mid = Math.floor(n/2);
    const midX = pts[mid][0];
    const dL = _closest(pts.slice(0, mid));
    const dR = _closest(pts.slice(mid));
    let delta = Math.min(dL, dR);

    // Build strip: points within delta of midline
    const strip = pts.filter(p => Math.abs(p[0] - midX) < delta);
    strip.sort((a,b) => a[1]-b[1]); // sort strip by y

    // Check at most 7 next points in strip
    for (let i=0;i<strip.length;i++) {
        for (let j=i+1;j<strip.length && strip[j][1]-strip[i][1]<delta;j++) {
            delta = Math.min(delta, dist(strip[i], strip[j]));
        }
    }
    return delta;
}

