// MAX POINTS ON A LINE (#149, NeetCode 150)
function maxPoints(points) {
    const n = points.length;
    if (n <= 2) return n;
    let result = 2;
    for (let i = 0; i < n; i++) {
        const slopes = new Map();
        for (let j = i+1; j < n; j++) {
            let dx = points[j][0] - points[i][0];
            let dy = points[j][1] - points[i][1];
            // Normalise slope as fraction dy/dx reduced by GCD
            if (dx === 0) { slopes.set('vertical', (slopes.get('vertical')||1)+1); continue; }
            if (dy === 0) { slopes.set('horizontal', (slopes.get('horizontal')||1)+1); continue; }
            const g = gcd(Math.abs(dx), Math.abs(dy));
            dx /= g; dy /= g;
            if (dx < 0) { dx=-dx; dy=-dy; } // canonical form: positive dx
            const key = `${dy}/${dx}`;
            slopes.set(key, (slopes.get(key)||1)+1);
        }
        for (const [,count] of slopes) result = Math.max(result, count);
    }
    return result;
}
